    <script>
        setTimeout(() => {
            var homePageSwiper = new Swiper(".homePageSwiper", {
                pagination: {
                    el: ".swiper-pagination",
                    clickable: true,
                },
                autoplay: {
                    delay: 7000,
                    disableOnInteraction: true,
                },
            });

            gsap.registerPlugin(ScrollTrigger, ScrollToPlugin);

            //const scrubValue = true;
            const scrubValue = 1;

            let container = document.querySelector('.container')

            ScrollTrigger.create({
                trigger: ".container",
                start: "top 36%",
                end: () => "+=" + (container.scrollWidth - window.innerWidth + 550),
                pin: '.everything',
                scrub: scrubValue,
                invalidateOnRefresh: true,
                markers: false,
            })

            let thumbNails = gsap.utils.toArray(".thumbnail");

            thumbNails.forEach((thumb, i) => {

                if (thumb.classList.contains('fakePin')) {

                    function prevAll(element) {
                        var result = [];

                        while (element = element.previousElementSibling)
                            result.push(element);
                        return result;
                    }

                    // console.log(prevAll(thumb))

                    var totalWidthToMove;

                    function getTotalWidthToMove() {

                        totalWidthToMove = 0;

                        prevAll(thumb).forEach((thumbBefore, i) => {

                            let style = thumbBefore.currentStyle || window.getComputedStyle(
                                thumbBefore);
                            let marginRight = parseInt(style.marginRight);

                            totalWidthToMove += thumbBefore.offsetWidth + marginRight;

                        });

                        console.log(totalWidthToMove);

                        return totalWidthToMove;

                    }

                    gsap.to(thumb, {
                        x: () => {
                            return -getTotalWidthToMove()
                        },
                        ease: "none",
                        scrollTrigger: {
                            trigger: ".wrapper",
                            start: 'center',
                            scrub: scrubValue,
                            invalidateOnRefresh: true,
                            end: () => "+=" + getTotalWidthToMove(),
                        }
                    });

                } else {

                    gsap.to(thumb, {
                        x: () => {
                            return -(container.scrollWidth - window.innerWidth)
                        },
                        ease: "none",
                        scrollTrigger: {
                            trigger: ".wrapper",
                            start: 'center',
                            scrub: scrubValue,
                            invalidateOnRefresh: true,
                            end: () => "+=" + (container.scrollWidth - window.innerWidth)
                        }
                    });
                }

            });

            /* Main navigation */
            const panelsSection = document.querySelector(".container");

            document.querySelectorAll(".anchor").forEach(anchor => {

                anchor.addEventListener("click", function(e) {

                    e.preventDefault();

                    const targetElem = document.querySelector(e.target.getAttribute("href"));

                    const containerOffset = panelsSection.offsetTop + targetElem.offsetLeft -
                    10; // 10 being the margin - probably better to get it like it was done above

                    gsap.to(window, {
                        scrollTo: {
                            y: containerOffset,
                            autoKill: false
                        },
                        duration: 1
                    });

                });

            });
        }, 50);
    </script>

    <style>
        body {
            overflow-x: hidden
        }
    </style>
